class stringx
{
  char data[16];
public:
  stringx(const char *, int = -1);
  stringx(const stringx &);
  ~stringx();
};

struct color32
{
  unsigned int value;
};

class FEMenuEntry
{
public:
  void SetSpecialColor(color32, color32);
};

class NamesMenu
{
public:
  void ResetCardFormat();
};

class HelpbarFE
{
public:
  void Reset();
  void ChangeBtn(int, bool, stringx);
  void Reformat();
};

struct FEEntityManager
{
  char pad[12];
  struct CameraRoll
  {
    char pad[16];
    int state;
  } *camera;
};

struct FEManager
{
  char pad0[12];
  FEEntityManager *em;
  char pad1[0x156a4 - 16];
  HelpbarFE *helpbar;
};

struct FrontendManager
{
  char pad[0xcd58];
  color32 col_unselected;
  color32 col_highlight;
};

extern FrontendManager frontendmanager;

class SaveLoadFrontEnd
{
  char pad0[0x4c];
  FEMenuEntry *highlighted;
  char pad1[0x13c - 0x50];
public:
  FEManager *manager;
private:
  char pad2[0x32a4 - 0x140];
  int back_menu;
  int back_sub_menu;
  int forward_menu;
  int forward_sub_menu;
  bool in_frontend;
  char pad3[0x32e4 - 0x32b5];
  FEMenuEntry *entry[3];
  char pad4[4];
  NamesMenu *NameMenu;

  void SetDState(int, bool = true, bool = false, bool = false);
  void BaseOnActivate();
  void setHigh(FEMenuEntry *, bool = true);

public:
  void OnActivate();
};

void SaveLoadFrontEnd::BaseOnActivate()
  __asm__("OnActivate__15FEGraphicalMenu");
void SaveLoadFrontEnd::setHigh(FEMenuEntry *, bool)
  __asm__("setHigh__6FEMenuP11FEMenuEntryb");

void SaveLoadFrontEnd::OnActivate()
{
  if (in_frontend && manager->em->camera->state == 0)
    manager->em->camera->state = 2;

  forward_menu = -1;
  forward_sub_menu = -1;
  back_menu = -1;
  back_sub_menu = -1;
  FEMenuEntry *tmp = highlighted;
  SetDState(0, false);
  for (int i = 0; i < 3; i++)
    entry[i]->SetSpecialColor(frontendmanager.col_unselected,
                              frontendmanager.col_highlight);
  BaseOnActivate();
  if (tmp)
    setHigh(tmp);
  NameMenu->ResetCardFormat();

  if (in_frontend)
  {
    manager->helpbar->Reset();
    manager->helpbar->ChangeBtn(1, true, stringx(""));
    manager->helpbar->ChangeBtn(2, false, stringx(""));
    manager->helpbar->Reformat();
  }
}
